/* 可编辑校园桌面。配置和便签仅保存在当前浏览器，按学校分别组织。 */
window.createCampusWidgets = function(ctx) {
  'use strict';
  const {state,school,esc,icon,footer,showModal,closeModal,navigate,renderPage,toast,currentCourses,isAuthenticated,inWeek,noticeRow,reminders,features}=ctx;
  const storageKey='xueyu-widget-layouts-v1', maxWidgets=16;
  const types={welcome:['leaf','校园寄语','一段寄语和校园插画'],schedule:['calendar','课程安排','选择星期，展示自己的课表'],news:['news','校园资讯','选择学校、学院或社团消息'],events:['people','社团活动','选择活动类别和展示数量'],shortcuts:['compass','快捷入口','自由组合常用校园功能'],services:['wrench','校园办事','成绩、图书、报修与校车服务'],portal:['graduation','功能资讯','竞赛、考试、兼职或二手信息'],reminders:['bell','待办提醒','展示本校个人待办'],note:['file','我的便签','写下目标、计划和小心情']};
  const sources={competitions:'竞赛活动',exams:'考试资讯',finals:'校内期末考试',jobs:'校园兼职',marketplace:'二手交易'};
  const routes={grades:['graduation','成绩查询',true],library:['book','图书借阅',true],'campus-card':['card','校园一卡通',true],repair:['wrench','校园报修',true],bus:['bus','校车时刻',true],features:['compass','功能中心'],schedule:['calendar','我的课表'],news:['news','校园资讯'],clubs:['people','社团广场'],map:['map','卡通校园地图'],forum:['chat','校园论坛'],messages:['message','校园私信'],volunteer:['heart','志愿学时'],guides:['compass','生活指南'],agent:['sparkle','找学屿'],competitions:['graduation','竞赛活动'],exams:['file','考试资讯'],finals:['calendar','校内期末考试'],jobs:['card','校园兼职'],marketplace:['book','二手交易']};
  const sizes={small:'小',medium:'中',wide:'大'}, accents=['sage','blue','sand','lilac','plain'];
  let data={};try {const x=JSON.parse(localStorage.getItem(storageKey)||'{}');if(x&&typeof x==='object'&&!Array.isArray(x))data=x;}catch{}
  let edit=null, drag=null, preview=false;
  const clone=x=>JSON.parse(JSON.stringify(x));
  const cleanText=(v,fallback,max)=>typeof v==='string'?v.slice(0,max):fallback;
  function campusToday(){const now=new Date();return {day:['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].indexOf(new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Shanghai',weekday:'short'}).format(now))+1,label:new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'long',day:'numeric',weekday:'long'}).format(now)};}
  function normalize(list){if(!Array.isArray(list))return null;const used=new Set();return list.slice(0,maxWidgets).filter(w=>w&&types[w.type]).map(w=>{
    let id=typeof w.id==='string'&&/^[a-zA-Z0-9-]{1,70}$/.test(w.id)?w.id:crypto.randomUUID();if(used.has(id))id=crypto.randomUUID();used.add(id);
    const source=Object.hasOwn(sources,w.source)?w.source:'competitions';
    return {id,type:w.type,title:cleanText(w.title,types[w.type][1],28),size:Object.hasOwn(sizes,w.size)?w.size:'medium',accent:accents.includes(w.accent)?w.accent:'sage',count:[1,2,3,4].includes(Number(w.count))?Number(w.count):3,source,category:['全部','学校','学院','社团','文艺','运动','学术','公益'].includes(w.category)?w.category:'全部',day:Number(w.day)>=1&&Number(w.day)<=7?Math.floor(Number(w.day)):'today',text:cleanText(w.text,'给今天留一点自己的空间。',500),links:Array.isArray(w.links)?[...new Set(w.links.map(r=>['ai','teaching'].includes(r)?'agent':r).filter(r=>Object.hasOwn(routes,r)))].slice(0,8):w.type==='services'?['grades','library','campus-card','repair','bus']:['features','schedule','map','agent']};
  });}
  function make(type,options={}){return normalize([{id:crypto.randomUUID(),type,...options}])[0];}
  function defaults(area){return area==='features'?[]:[
    make('schedule',{title:'今日课程',day:'today',count:3,accent:'sage'}),
    make('reminders',{title:'今天，慢慢完成',accent:'sand',count:3}),
    make('note',{title:'留一点时间给自己',size:'wide',accent:'lilac',text:'认真上课，也好好生活。\n写下一个小目标，给今天留一点期待。'})
  ];}
  function saved(area){return normalize(data[school().id]?.[area])??defaults(area);}
  function isPinned(route){return saved('home').some(w=>['shortcuts','services'].includes(w.type)&&w.links.includes(route));}
  function pinRoute(route){
    if(!Object.hasOwn(routes,route)){toast('这个入口暂时不能添加为快捷方式。');return false;}
    if(edit){toast('你还有未保存的布局草稿，请先保存或取消，再添加首页快捷。');return false;}
    const list=clone(saved('home'));
    if(list.some(w=>['shortcuts','services'].includes(w.type)&&w.links.includes(route))){toast('这个快捷入口已经在你的首页。');return false;}
    const group=list.find(w=>w.type==='shortcuts'&&w.links.length<8);
    if(group)group.links.push(route);
    else if(list.length<maxWidgets)list.push(make('shortcuts',{title:'我选的快捷入口',links:[route],size:'medium',accent:'plain'}));
    else{toast('首页最多放置 16 个小组件，请先移除一个再添加。');return false;}
    const next={...data,[school().id]:{...data[school().id],home:list}};
    try{localStorage.setItem(storageKey,JSON.stringify(next));}catch{toast('浏览器未允许保存，快捷入口暂未添加。');return false;}
    data=next;renderPage();toast(`已将“${routes[route][1]}”添加到首页，可在自定义中调整。`);return true;
  }
  function editing(area){return edit?.school===school().id&&edit.area===area;}
  function items(area){return editing(area)?edit.items:saved(area);}
  function begin(area){if(!['home','features'].includes(area))return;if(edit){if(!editing(area)){toast('请先保存或取消当前布局草稿，再编辑另一个页面。');navigate(edit.area==='home'?'home-layout':'service-layout');}else renderPage();return;}edit={area,school:school().id,items:clone(saved(area)),history:[]};preview=false;renderPage();}
  function pushHistory(){edit.history.push(clone(edit.items));if(edit.history.length>30)edit.history.shift();}
  function find(id){return edit?.school===school().id?edit.items.find(w=>w.id===id):null;}
  function redraw(id){renderPage();if(id)requestAnimationFrame(()=>document.querySelector(`[data-widget-id="${id}"] .widget-grip`)?.focus({preventScroll:true}));}
  function stopDrag(){if(!drag)return;try{drag.grip.releasePointerCapture(drag.pointerId);}catch{}drag.card.style.transform='';drag.card.classList.remove('widget-dragging');document.querySelectorAll('.widget-drop-target').forEach(e=>e.classList.remove('widget-drop-target'));document.body.classList.remove('widget-is-dragging');drag=null;}
  const go=(r,text='查看全部')=>r===state.route?'':`<button class="widget-more" data-route="${r}">${text}${icon('chevron')}</button>`;
  const blank=text=>`<p class="widget-empty-text">${esc(text)}</p>`;
  function courseRows(w){const day=w.day==='today'?campusToday().day:w.day;const rows=currentCourses().filter(c=>c.weekday===day&&inWeek(c,state.week)).sort((a,b)=>a.start.localeCompare(b.start)).slice(0,w.count);return `<div class="widget-subline">${w.day==='today'?'今天 · ':''}周${'一二三四五六日'[day-1]}<span>${state.imports[school().id]?'导入课表':'示例课表'} · 示例第 ${state.week} 教学周</span></div>${rows.length?rows.map(c=>`<button class="widget-course" data-action="course" data-id="${esc(c.id)}"><span>${esc(c.start)}<small>${esc(c.end)}</small></span><div><strong>${esc(c.name)}</strong><small>${esc(c.location)}</small></div>${icon('chevron')}</button>`).join(''):blank('这一天没有课程，留点时间给自己。')}`;}
  function portalRows(w){if(w.source==='finals')return `<div class="widget-final-note">${icon('calendar')}<strong>${isAuthenticated()?'等待教务发布考试安排':'认证后查看本学期课程'}</strong><p>本校课程考试单独展示，时间与考场待教务确认。</p>${go('finals','进入课程考试区')}</div>`;const rows=features.widgetItems(w.source).filter(x=>!x.sold).slice(0,w.count);return `<div class="widget-subline">${esc(sources[w.source])}<span>${['exams','competitions'].includes(w.source)?'以官方当届公告为准':'本校示例信息'}</span></div>${rows.length?rows.map(x=>`<button class="widget-info-row" data-action="feature-detail" data-id="${esc(x.id)}"><span class="widget-row-icon">${icon(w.source==='exams'?'file':w.source==='competitions'?'graduation':w.source==='jobs'?'card':'book')}</span><span><strong>${esc(x.title)}</strong><small>${esc(x.category)}${x.price!==undefined?' · '+(typeof x.price==='number'?'¥'+x.price:x.price):''}</small></span>${icon('chevron')}</button>`).join(''):blank('暂时没有相关信息。')}`;}
  function content(w){switch(w.type){
    case 'welcome':return `<div class="widget-welcome-content"><div><span>${esc(school().shortName)} · YOUR CAMPUS, YOUR WAY</span><h2>${esc(w.title)}</h2><p>${esc(w.text)}</p><button data-route="${state.route==='features'?'clubs':'features'}">${state.route==='features'?'去发现校园活动':'探索校园的更多可能'} ${icon('arrow')}</button></div><img src="assets/campus-illustration.svg" alt="树木环绕的校园插画"/></div>`;
    case 'schedule':return courseRows(w);
    case 'news':{const rows=school().notices.filter(n=>w.category==='全部'||n.category===w.category).slice(0,w.count);return `<div class="widget-subline">${w.category==='全部'?'学校 · 学院 · 社团':esc(w.category)+'消息'}<span>本校资讯</span></div><div class="widget-notices">${rows.length?rows.map(n=>noticeRow(n)).join(''):blank('该分类暂无消息。')}</div>`;}
    case 'events':{const rows=school().events.filter(x=>w.category==='全部'||x.category===w.category).slice(0,w.count);return `<div class="widget-subline">${w.category==='全部'?'发现校园里的热爱':esc(w.category)+'活动'}<span>演示活动</span></div>${rows.length?rows.map(x=>`<button class="widget-event" data-action="event" data-id="${esc(x.id)}"><img src="${esc(x.cover)}" alt=""/><span><strong>${esc(x.title)}</strong><small>${esc(x.date)} · ${esc(x.category)}</small></span>${icon('chevron')}</button>`).join(''):blank('这个分类暂时没有活动。')}`;}
    case 'services':case 'shortcuts':return `<div class="widget-shortcut-grid">${w.links.map(r=>`<button ${routes[r][2]?'data-action':'data-route'}="${r}"><span>${icon(routes[r][0])}</span><strong>${routes[r][1]}</strong></button>`).join('')}</div>`;
    case 'portal':return portalRows(w);
    case 'reminders':{const rows=reminders().filter(x=>!state.completed.includes(x.id)).slice(0,w.count);return `<div class="widget-subline">留住重要的小事<span>仅本地待办</span></div>${rows.length?rows.map(x=>`<div class="widget-reminder"><button class="check-btn" data-action="complete" data-id="${esc(x.id)}" role="checkbox" aria-checked="false" aria-label="完成${esc(x.title)}"></button><span><strong>${esc(x.title)}</strong><small>${esc(x.due)}</small></span></div>`).join(''):blank('今天的待办都完成啦。')}${goReminder()}`;}
    case 'note':return `<div class="widget-note-content"><span aria-hidden="true">“</span><p>${esc(w.text)}</p><small>A LITTLE SPACE, JUST FOR YOU</small></div>`;
    default:return '';
  }}
  function goReminder(){return `<button class="widget-add-todo" data-action="add-reminder">${icon('plus')}添加提醒</button>`;}
  function more(w){const r={schedule:'schedule',news:'news',events:'clubs',shortcuts:'features',services:'features',portal:w.source};return r[w.type]?go(r[w.type]):'';}
  function widget(w,index,total,area){const isEdit=editing(area)&&!preview;return `<article class="campus-widget widget-${w.type} widget-size-${w.size} widget-accent-${w.accent} ${isEdit?'widget-editable':''}" data-widget-id="${w.id}" aria-label="${esc(w.title)}小组件">${isEdit?`<div class="widget-edit-head"><button class="widget-grip" data-widget-grip="${w.id}" aria-label="拖动${esc(w.title)}，当前第${index+1}项" title="按住拖动"><span aria-hidden="true">⠿</span></button><span class="widget-position">${String(index+1).padStart(2,'0')} / ${String(total).padStart(2,'0')}</span><span class="widget-edit-kind">${types[w.type][1]}</span><button data-action="widget-config" data-id="${w.id}" class="widget-config-btn" aria-label="设置${esc(w.title)}">${icon('settings')}设置</button><button class="widget-remove" data-action="widget-remove" data-id="${w.id}" aria-label="移除${esc(w.title)}">${icon('x')}</button></div>`:''}<div class="widget-preview-body" ${isEdit?'inert':''}>${w.type==='welcome'?'':`<div class="widget-heading"><h2>${icon(types[w.type][0])}${esc(w.title)}</h2>${more(w)}</div>`}${content(w)}</div>${isEdit?`<div class="widget-edit-foot"><span class="widget-size-control" aria-label="组件大小">${Object.entries(sizes).map(([v,t])=>`<button class="${w.size===v?'selected':''}" data-action="widget-size" data-id="${w.id}" data-size="${v}" aria-label="将${esc(w.title)}设为${t}组件" aria-pressed="${w.size===v}">${t}</button>`).join('')}</span><div class="widget-move-buttons"><button data-action="widget-move-up" data-id="${w.id}" ${index===0?'disabled':''} aria-label="上移${esc(w.title)}">↑ 上移</button><button data-action="widget-move-down" data-id="${w.id}" ${index===total-1?'disabled':''} aria-label="下移${esc(w.title)}">↓ 下移</button></div></div>`:''}</article>`;}
  function toolbar(area){
    if(!editing(area))return `<section class="widget-toolbar widget-toolbar-rest" aria-label="桌面布局编辑"><span>${icon('settings')}我的${area==='home'?'今日安排':'服务布局'}<small>${saved(area).length} 个小组件</small></span><button class="secondary-btn" data-action="widget-edit" data-id="${area}">${icon('plus')}自定义</button></section>`;
    return `<section class="widget-toolbar is-editing" aria-label="桌面布局编辑"><div class="widget-toolbar-title"><span class="widget-toolbar-icon">${icon('settings')}</span><div><strong>${preview?'看看你的新桌面':'把校园，摆成喜欢的样子'}</strong><small>${preview?'当前为预览，返回编辑后可继续调整。':'拖动圆点手柄，或用上移 / 下移按钮；修改保存后生效。'}</small></div></div><div class="widget-toolbar-actions">${preview?'':`<button class="secondary-btn" data-action="widget-library">${icon('plus')}添加小组件</button><button class="widget-quiet-btn" data-action="widget-undo" ${edit.history.length?'':'disabled'}>撤销</button>`}<button class="widget-quiet-btn" data-action="widget-preview">${preview?'返回编辑':'预览'}</button><button class="widget-quiet-btn" data-action="widget-cancel">取消</button><button class="primary-btn" data-action="widget-save">${icon('check')}保存布局</button></div></section>${preview?'':`<div class="widget-edit-note"><span>${edit.items.length} / ${maxWidgets} 个小组件 · ${esc(school().name)} · 尚未保存</span><button data-action="widget-reset">恢复默认布局</button></div>`}`;
  }
  function page(area){
    const list=items(area),s=school();
    const header=area==='home'?`<div class="greeting widget-greeting widget-greeting-refresh"><div><div class="eyebrow">${esc(campusToday().label)} · ${esc(s.shortName)}</div><h1>嗨，${isAuthenticated()?esc(s.student.name):'同学'}<span class="widget-greeting-spark">${icon('sparkle')}</span></h1><p class="greeting-sub">把今天，过成喜欢的样子。</p></div><span class="widget-home-stamp">有自己的节奏，也很好。</span></div>`:`<div class="page-heading"><div><div class="eyebrow">MY SERVICE SPACE</div><h1>我的服务布局</h1><p>之前自定义的布局仍在这里，也可以自由组合新模块。</p></div><button class="secondary-btn" data-route="features">${icon('left')}返回功能</button></div>`;
    return `${header}${toolbar(area)}<div class="campus-widget-grid ${editing(area)&&!preview?'widget-grid-editing':''}" data-widget-area="${area}">${list.map((w,i)=>widget(w,i,list.length,area)).join('')}${!list.length?`<div class="widget-empty-board">${icon('plus')}<h2>留一块空白，装下你的校园生活</h2><p>选择需要的模块，再摆成你习惯的样子。</p><button class="primary-btn" data-action="${editing(area)?'widget-library':'widget-edit'}" data-id="${area}">${editing(area)?'添加小组件':'开始自定义'}</button></div>`:''}</div><div class="widget-layout-caption"><span>${icon('shield')}仅保存在当前浏览器 · 按学校独立保存</span>${editing(area)?'<span>预览与取消不会覆盖已保存布局</span>':'<span>功能页可将喜欢的服务添加到此桌面</span>'}</div>${footer()}`;
  }
  function library(){if(!edit)return;showModal(`<div class="modal-content widget-library-modal"><span class="modal-tag">WIDGET GALLERY · ${esc(school().shortName)}</span><h2>校园生活，按需组合。</h2><p class="modal-intro">选择一个小组件，再设置它的大小、标题和内容。同类组件也可以添加多个。</p><div class="widget-library-grid">${Object.entries(types).map(([type,[i,t,d]])=>`<button class="widget-library-card" data-action="widget-add" data-id="${type}" ${edit.items.length>=maxWidgets?'disabled':''}><span class="widget-library-preview preview-${type}">${icon(i)}<i></i><i></i></span><strong>${t}</strong><small>${d}</small><em>${icon('plus')}添加</em></button>`).join('')}</div><p class="form-note">${edit.items.length} / ${maxWidgets} 个小组件；添加后可在组件“设置”中调整内容。</p></div>`,true);}
  const option=(value,text,current)=>`<option value="${esc(value)}" ${String(value)===String(current)?'selected':''}>${esc(text)}</option>`;
  function configure(id){const w=find(id);if(!w)return;const specific={
    welcome:`<label class="form-label" for="widget-text">校园寄语</label><textarea class="form-input" id="widget-text" name="text" rows="3" maxlength="500">${esc(w.text)}</textarea>`,
    note:`<label class="form-label" for="widget-text">便签内容</label><textarea class="form-input" id="widget-text" name="text" rows="6" maxlength="500" placeholder="写下你的小目标、计划或心情…">${esc(w.text)}</textarea><p class="form-note">仅你当前浏览器可见，不会发送到论坛或 AI。</p>`,
    schedule:`<label class="form-label" for="widget-day">展示哪一天</label><select class="form-input" id="widget-day" name="day">${option('today','跟随今天（上海时区）',w.day)}${Array.from({length:7},(_,i)=>option(i+1,'固定周'+'一二三四五六日'[i],w.day)).join('')}</select><p class="form-note">跟随今天会自动切换星期；教学周为当前选择的示例周次，可在完整课表中调整。</p>`,
    news:`<label class="form-label" for="widget-category">消息来源</label><select class="form-input" id="widget-category" name="category">${['全部','学校','学院','社团'].map(c=>option(c,c==='全部'?'全部消息':c+'消息',w.category)).join('')}</select>`,
    events:`<label class="form-label" for="widget-category">活动类型</label><select class="form-input" id="widget-category" name="category">${['全部','文艺','运动','学术','公益'].map(c=>option(c,c==='全部'?'全部活动':c+'活动',w.category)).join('')}</select>`,
    portal:`<label class="form-label" for="widget-source">展示内容</label><select class="form-input" id="widget-source" name="source">${Object.entries(sources).map(([v,t])=>option(v,t,w.source)).join('')}</select><p class="form-note">校内期末考试独立于语言、资格考试；组件只展示你选定的信息类型。</p>`,
    shortcuts:`<fieldset class="widget-link-picker"><legend>选择快捷入口（最多 8 个）</legend>${Object.entries(routes).map(([r,[i,t]])=>`<label><input type="checkbox" name="links" value="${r}" ${w.links.includes(r)?'checked':''}/>${icon(i)}${t}</label>`).join('')}</fieldset>`
  }[w.type==='services'?'shortcuts':w.type]||'';
    showModal(`<div class="modal-content"><span class="modal-tag">${types[w.type][1]} · 小组件设置</span><h2>让这个模块，更像你。</h2><form id="widget-config-form" data-id="${id}" data-school="${school().id}" data-area="${edit.area}"><label class="form-label" for="widget-title">模块标题</label><input id="widget-title" class="form-input" name="title" maxlength="28" value="${esc(w.title)}" required/><div class="widget-form-pair"><div><label class="form-label" for="widget-size">模块大小</label><select id="widget-size" class="form-input" name="size">${Object.entries(sizes).map(([v,t])=>option(v,t+'组件',w.size)).join('')}</select></div><div><label class="form-label" for="widget-accent">模块配色</label><select id="widget-accent" class="form-input" name="accent">${[['sage','鼠尾草绿'],['blue','晴空蓝'],['sand','暖沙色'],['lilac','浅丁香'],['plain','纯白']].map(([v,t])=>option(v,t,w.accent)).join('')}</select></div></div>${specific}${['schedule','news','events','portal','reminders'].includes(w.type)?`<label class="form-label" for="widget-count">展示数量</label><select id="widget-count" class="form-input" name="count">${[1,2,3,4].map(n=>option(n,n+' 条',w.count)).join('')}</select>`:''}<p class="form-error" id="widget-form-error" role="alert"></p><button class="primary-btn full-btn" type="submit">应用到布局草稿 ${icon('check')}</button><p class="form-note">应用后可继续调整，最后点击“保存布局”生效。</p></form></div>`);
  }
  function move(id,offset){const w=find(id);if(!w||preview)return;const from=edit.items.indexOf(w),to=from+offset;if(to<0||to>=edit.items.length)return;pushHistory();edit.items.splice(to,0,edit.items.splice(from,1)[0]);redraw(id);toast(`已将“${w.title}”移到第 ${to+1} 位`);}
  const actions={
    'widget-edit':area=>begin(area),
    'widget-open-home':()=>{navigate('home-layout');begin('home');},
    'widget-open-services':()=>navigate('service-layout'),
    'widget-library':library,
    'widget-add':type=>{if(!edit||!types[type]||edit.items.length>=maxWidgets)return;pushHistory();const w=make(type,{title:types[type][1],text:type==='note'?'这周的小目标：\n读完一本书，留点时间运动。':undefined});edit.items.push(w);closeModal();redraw();configure(w.id);},
    'widget-config':configure,
    'widget-remove':id=>{if(!find(id))return;pushHistory();edit.items=edit.items.filter(w=>w.id!==id);redraw();toast('组件已从草稿移除，可撤销。');},
    'widget-size':(id,el)=>{const w=find(id);if(!w||!Object.hasOwn(sizes,el.dataset.size)||w.size===el.dataset.size)return;pushHistory();w.size=el.dataset.size;redraw(id);},
    'widget-move-up':id=>move(id,-1),'widget-move-down':id=>move(id,1),
    'widget-undo':()=>{if(!edit?.history.length)return;edit.items=edit.history.pop();redraw();toast('已撤销上一步');},
    'widget-reset':()=>{if(!edit)return;pushHistory();edit.items=defaults(edit.area);redraw();toast('默认布局已应用到草稿，保存后生效。');},
    'widget-preview':()=>{if(!edit)return;preview=!preview;renderPage();},
    'widget-cancel':()=>{stopDrag();edit=null;preview=false;closeModal();renderPage();toast('已取消本次布局修改');},
    'widget-save':()=>{if(!edit||edit.school!==school().id)return;const next={...data,[school().id]:{...data[school().id],[edit.area]:normalize(edit.items)}};try{localStorage.setItem(storageKey,JSON.stringify(next));}catch{toast('浏览器未允许保存，请保持页面并继续编辑。');return;}data=next;edit=null;preview=false;closeModal();renderPage();toast('布局已保存，刷新后依然保留。');}
  };
  function onSubmit(e){const f=e.target;if(f.id!=='widget-config-form')return;e.preventDefault();const w=find(f.dataset.id);if(!w||f.dataset.school!==school().id||f.dataset.area!==edit.area){closeModal();toast('布局已变化，请重新打开组件设置。');return;}const v=new FormData(f),title=String(v.get('title')||'').trim(),links=v.getAll('links').filter(r=>Object.hasOwn(routes,r));if(!title||['shortcuts','services'].includes(w.type)&&(links.length===0||links.length>8)){document.querySelector('#widget-form-error').textContent=!title?'请填写模块标题。':'请选择 1–8 个快捷入口。';return;}pushHistory();const next={...w,title,size:v.get('size'),accent:v.get('accent')};for(const k of ['category','source','text','day','count'])if(v.has(k))next[k]=v.get(k);if(['shortcuts','services'].includes(w.type))next.links=links;Object.assign(w,normalize([next])[0]);closeModal();redraw(w.id);toast('组件内容已应用到草稿');}
  function onPointerDown(e){const grip=e.target.closest('[data-widget-grip]');if(!grip||!edit||preview||e.button!==0)return;const card=grip.closest('[data-widget-id]');if(!card||!find(card.dataset.widgetId))return;stopDrag();drag={grip,card,id:card.dataset.widgetId,pointerId:e.pointerId,startX:e.clientX,startY:e.clientY,target:null,active:false};grip.setPointerCapture(e.pointerId);e.preventDefault();}
  function onPointerMove(e){if(!drag||e.pointerId!==drag.pointerId)return;const dx=e.clientX-drag.startX,dy=e.clientY-drag.startY;if(!drag.active&&Math.hypot(dx,dy)<6)return;drag.active=true;drag.card.classList.add('widget-dragging');document.body.classList.add('widget-is-dragging');drag.card.style.transform=`translate(${dx}px,${dy}px)`;const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-widget-id]');document.querySelectorAll('.widget-drop-target').forEach(el=>el.classList.remove('widget-drop-target'));drag.target=target&&target!==drag.card&&target.closest('[data-widget-area]')===drag.card.closest('[data-widget-area]')?target.dataset.widgetId:null;if(drag.target)target.classList.add('widget-drop-target');if(e.clientY<120)window.scrollBy(0,-12);else if(e.clientY>window.innerHeight-100)window.scrollBy(0,12);e.preventDefault();}
  function onPointerUp(e){if(!drag||e.pointerId!==drag.pointerId)return;const {id,target,active}=drag;stopDrag();if(!active||!target||!find(id)||!find(target))return;const from=edit.items.findIndex(w=>w.id===id),to=edit.items.findIndex(w=>w.id===target);pushHistory();edit.items.splice(to,0,edit.items.splice(from,1)[0]);redraw(id);toast(`已移动到第 ${to+1} 位`);}
  function onPointerCancel(){stopDrag();}
  function schoolChanged(){stopDrag();edit=null;preview=false;}
  function onKeyDown(e){if(e.key==='Escape'&&drag)stopDrag();}
  return {page,pinRoute,isPinned,actions,onSubmit,onPointerDown,onPointerMove,onPointerUp,onPointerCancel,onKeyDown,schoolChanged};
};
